struct import_t* get_imports(struct MACH0_(obj_t)* bin) {
    if (!bin || !bin->symtab) {
        return NULL;
    }

    uint32_t num_symbols = bin->symtab->num_symbols;
    struct symbol_t* symbols = bin->symtab->symbols;
    struct import_t* imports = malloc(sizeof(struct import_t) * num_symbols);
    if (!imports) {
        return NULL;
    }

    bin->imports = imports;
    bin->import_size = num_symbols;

    for (uint32_t i = 0; i < num_symbols; ++i) {
        if (symbols[i].type == STT_NOTYPE || symbols[i].binding != STB_GLOBAL) {
            continue;
        }

        char* name = get_symbol_name(bin, &symbols[i]);
        if (!name) {
            continue;
        }

        if (filter_symbol(name)) {
            free(name);
            continue;
        }

        imports[i].name = name;
    }

    return imports;
}

struct import_t* get_import_symbols(struct MACH0_(obj_t)* bin) {
    if (!bin || !bin->symbols.undef) {
        return NULL;
    }

    struct import_t* imports = (struct import_t*)malloc(bin->symbols.undef->count * sizeof(struct import_t));
    if (!imports) {
        return NULL;
    }

    for (size_t i = 0; i < bin->symbols.undef->count; i++) {
        char* symbol_name = get_symbol_name(bin, i, STN_UNDEF);
        if (!symbol_name) {
            continue;
        }

        if (is_valid_symbol_name(symbol_name)) {
            imports[i].name = strdup(symbol_name);
            filter_symbol_name(imports[i].name);
        }
    }

    bin->imports.size = bin->symbols.undef->count;
    return imports;
}

#include <stdlib.h>
#include <string.h>

struct import_t* get_imports(struct MACH0_(obj_t)* bin) {
    // Check the validity of the binary object and its symbol table
    if (!bin || !bin->symtab || !bin->symtab->nbuckets) {
        return NULL;
    }

    // Allocate memory for the imports based on the number of undefined symbols
    size_t num_imports = bin->symtab->nlocalsyms;
    struct import_t* imports = calloc(num_imports, sizeof(struct import_t));
    if (!imports) {
        return NULL;
    }

    for (size_t i = 0; i < num_imports; ++i) {
        const char* sym_name = bin->symtab->symbols[i].name;
        if (!sym_name || !*sym_name) {
            continue;
        }

        // Duplicate and filter the symbol name
        char* filtered_name = strdup(sym_name);
        if (!filtered_name) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(imports[j].name);
            }
            free(imports);
            return NULL;
        }

        // Store the filtered name in the import_t structure
        imports[i].name = filtered_name;
    }

    // Update the binary object's import size
    bin->import_size = num_imports;

    return imports;
}

