struct import_t* get_imports(struct MACH0_(obj_t)* bin) {
    if (!bin || !bin->symtab || !bin->symtab->num_symbols) {
        return NULL;
    }

    size_t num_undef = 0;
    for (size_t i = 0; i < bin->symtab->num_symbols; i++) {
        if (MACH0_(symtab_get_type)(bin, i) == STT_UNDEF) {
            num_undef++;
        }
    }

    struct import_t* imports = calloc(num_undef, sizeof(struct import_t));
    if (!imports) {
        return NULL;
    }

    size_t idx = 0;
    for (size_t i = 0; i < bin->symtab->num_symbols; i++) {
        if (MACH0_(symtab_get_type)(bin, i) == STT_UNDEF) {
            const char* name = MACH0_(symtab_get_name)(bin, i);
            if (name && name[0] != '\0') {
                char* filtered_name = strdup(name);
                if (!filtered_name) {
                    // Memory allocation failed, clean up and return NULL
                    for (size_t j = 0; j < idx; j++) {
                        free(imports[j].name);
                    }
                    free(imports);
                    return NULL;
                }
                imports[idx].name = filtered_name;
                idx++;
            }
        }
    }

    bin->imports = imports;
    bin->num_imports = idx;
    return imports;
}
